const DRAFT_NOTE = (slug) => ` STARTING POINT: an earlier run was interrupted after writing a data-only draft at ${REPO}/drafts/compounds/${slug}.yaml plus entries in ${REPO}/src/data/sources/${slug}.yaml and (if present) ${REPO}/src/i18n/en/glossary/${slug}.json. Its research notes file was lost, so treat every value as UNVERIFIED: re-check each fact, structured study and source against its primary record before keeping it, drop sources you do not cite, and add what is missing. Write the final data file to src/data/compounds/${slug}.yaml, then delete drafts/compounds/${slug}.yaml.`

