const groups = (args && args.length) ? ASSIGNMENTS.filter((a) => args.includes(a.key)) : []
if (!groups.length) throw new Error('pass args: list of assignment keys')
log(`groups: ${groups.map((g) => g.key).join(', ')}`)

phase('Write')
const results = await pipeline(
  groups,
  (a) =>
    agent(`${PREAMBLE}\n\n${a.brief}\n\nFILES YOU OWN (create/write only these, paths relative to ${REPO}):\n${a.files.map((f) => '- ' + f).join('\n')}\n\nReturn the structured summary. Be candid in contract_issues.`, {
      label: `write:${a.key}`,
      phase: 'Write',
      schema: WRITE_SCHEMA,
    }),
  (w, a) =>
    agent(`${PREAMBLE}\n\nYOU ARE THE INDEPENDENT FACT-CHECKER for the "${a.key}" content another agent just wrote. Assume it contains errors; your job is to find and fix them.\n\nFiles to check (you may edit all of them):\n${a.files.map((f) => '- ' + f).join('\n')}\n\nThe writer reported: ${JSON.stringify(w)}\n\nDo, in order:\n1. EVERY source in the group's sources file: look it up (PubMed get_article_metadata by PMID, convert_article_ids / search by DOI; fetch regulator and law URLs). Confirm authors, title, journal, year, DOI, PMID match the record exactly. Fix or remove wrong ones (and the claims that depended on them).\n2. EVERY structured study (compound groups): confirm species, n (subjects actually studied), design, funding, group (originating vs independent), blinded/controlled against the abstract or full text.\n3. Claims: check every number, date, regulatory or legal statement, and every efficacy/safety claim against its cited source. Fix overstatements (animal results written as if human; 'shows' where 'suggests' is right; wrong <Claim level>). Legal statements must match the statute text.\n4. Regulatory facts: re-verify each status and date against primary sources. Wherever the July 2026 FDA PCAC vote appears, check all five canonical elements from the guide.\n5. Guardrails (guide §1, §6): no dosing guidance, no 'safe/proven' for unapproved use, no superlatives, no sourcing hints, no testimonials; studied doses only inside study descriptions in <Q>; no commerce words in link text.\n6. The opposite failure: anything unfairly negative or scaremongering? Is genuinely promising evidence acknowledged? Is the B1 reading level actually met on safety/legal pages (rewrite long sentences)?\n7. Internal links only to the planned routes; no '# ' h1 in bodies. Page photos: licence genuinely allowed (check the Commons file page), alt text describes what matters, nothing that looks like a product, vial or glamorised injecting. glance.main_risk and summary items: plain, accurate, supported by the page.\n8. Run the validator for these files and get to 0 errors.\nFix problems directly in the files. Append a 'Fact-check log' section to the group's research notes file listing what you checked and changed.`, {
      label: `verify:${a.key}`,
      phase: 'Verify',
      schema: VERIFY_SCHEMA,
    }).then((v) => ({ key: a.key, write: w, verify: v })),
)
return results
